    if s is None:
        return None
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        return None
    return dt


def main():
    with open(sys.argv[1]) as f:
        data = json.load(f)

    as_of = parse_iso(data["as_of"])

    items = []
    for r in data["reminders"]:
        if r.get("completed", False):
            continue
        due = r.get("due")
        if due is None:
            continue
        dt = parse_iso(due)
        if dt is None:
            continue
        if dt <= as_of:
            due_utc = dt.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
            items.append((dt, r["id"], r["title"], due_utc))

    items.sort(key=lambda x: (x[0], x[1]))

    results = [
        {"id": item[1], "title": item[2], "due_utc": item[3]}
        for item in items
    ]
    print(json.dumps(results))


if __name__ == "__main__":
    main()
